def sha(p):
 h=hashlib.sha256()
 with p.open('rb') as f:
  for b in iter(lambda:f.read(1024*1024),b''): h.update(b)
 return h.hexdigest()
def rel(p): return str(p.relative_to(ROOT)).replace('\\','/')
def append_rows(path, rows, key_index=0):
 existing={r[key_index] for r in csv.reader(path.open(encoding='utf-8')) if r}
 with path.open('a',newline='',encoding='utf-8') as f:
  w=csv.writer(f)
  for r in rows:
   if r[key_index] not in existing: w.writerow(r)
def append(path,text):
 with path.open('a',encoding='utf-8') as f:f.write('\n'+text.rstrip()+'\n')
